mapper.select:
SELECT CASE WHEN FP.FINPROD_TYPE2 = '${F01}' THEN TEMP.AMT*100 ELSE TEMP.AMT END AMT, TEMP.TDY_FLOAT_INGPL floatIngpl, TEMP.COST FROM (SELECT SUM(TDY_FLOAT_INGPL) TDY_FLOAT_INGPL, SUM(DSC_COST_AMT) COST, SUM(SHARE_AMT) AMT, PORTFOLIO_ID, FINPROD_ID FROM PTL_SEC_VALUTION WHERE PORTFOLIO_ID = #{portfolioId} AND CDATE = #{date,jdbcType=DATE} GROUP BY PORTFOLIO_ID, FINPROD_ID ) TEMP LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = TEMP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = TEMP.FINPROD_ID
and FPT.TYPE_9 = #{type2}
and FPT.TYPE_10 = #{type3}
and FPT.TYPE_11 = #{type4}
and FPT.TYPE_12 = #{type5}
